<template>
    <div class="page">
        <div class="login-contents" :class="itTop">
            <div v-if="!isCode" class="login-tops">
                <div class="jk-wel">Welcome</div>
                <div class="t-wels">
                    <div class="login-title">欢迎登录系统</div>
                    <div class="login-title1" @click="ecyzlist">谷歌验证</div>
                </div>
                <!-- 用户名输入 -->
                <div class="login-list">
                    <img class="login-img" src="@/assets/images/user_icon.webp">
                    <input 
                        v-model="form.account"
                        class="usput"
                        @focus="isFocused = true"
                        @blur="isFocused = false"
                        placeholder="请输入用户名"
                    />
                    <div class="focus-border"></div>
                </div>
                
                <!-- 密码输入 -->
                <div class="login-list">
                    <img class="login-img" src="@/assets/images/lock_icon.webp">
                    <input 
                        v-model="form.passwd"
                        class="usput"
                        :type="showPassword ? 'text' : 'password'"
                        @focus="isFocused = true"
                        @blur="isFocused = false"
                        placeholder="请输入密码"
                    />
                    <div class="focus-border"></div>
                    <img class="login-img1" v-if="!showPassword" @click="togglePassword" src="@/assets/images/eyeClosed.webp">
                    <img class="login-img1" v-if="showPassword" @click="togglePassword" src="@/assets/images/eyes.webp">
                </div>
                
                <!-- 验证码输入 -->
                <div class="login-list">
                    <img class="login-img" src="@/assets/images/verify_icon.webp">
                    <input 
                        v-model="form.captcha"
                        class="usput"
                        @focus="isFocused = true"
                        @blur="isFocused = false"
                        placeholder="请输入验证码"
                    />
                    <div class="focus-border"></div>
                    <div class="login-yzm1" @click="getCode">
                        <img :src="codeimg" alt="验证码" class="list-code" />
                    </div>
                </div>
                <!-- 谷歌验证 -->
                <div class="login-list" v-if="ecyz">
                    <img class="login-img" src="@/assets/images/guge_icon.webp">
                    <input 
                        v-model="form.code"
                        class="usput"
                        @focus="isFocused = true"
                        @blur="isFocused = false"
                        placeholder="请输入用户名"
                    />
                    <div class="focus-border"></div>
                </div>
                <!-- 记住密码 -->
                <div class="jzmm">
                    <img class="jzmm-img" v-if="!rememberPassword" @click="toggleRememberPassword" src="@/assets/images/checkicon.webp">
                    <img class="jzmm-img" v-if="rememberPassword" @click="toggleRememberPassword" src="@/assets/images/checkicons.webp">
                    <div class="jzmm-t">记住账号密码</div>
                </div>
                
                <!-- 登录按钮 -->
                <div class="login-bt" @click="submitForm">立即登录</div>
            </div>
            
            <!-- 浏览器下载区域 -->
            <div class="lrxz">
                <div class="lrxs">
                    <div class="lrq-list" @click="bdownload(1)">
                        <div class="tile-icon">
                            <img class="lrq-img" src="@/assets/images/google_logo.webp">
                        </div>
                        <div class="tile-title">Chrome下载</div>
                    </div>
                    <div class="lrq-list" @click="bdownload(4)">
                        <div class="tile-icon">
                            <img class="lrq-img" src="@/assets/images/firefox_logo.webp">
                        </div>
                        <div class="tile-title">火狐下载</div>
                    </div>
                    <div class="lrq-list" @click="bdownload(3)">
                        <div class="tile-icon">
                            <img class="lrq-img" src="@/assets/images/safari_logo.webp">
                        </div>
                        <div class="tile-title">Safari下载</div>
                    </div>
                    <div class="lrq-list" @click="bdownload(2)">
                        <div class="tile-icon">
                            <img class="lrq-img" src="@/assets/images/uc_logo.webp">
                        </div>
                        <div class="tile-title">UC下载</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'
import { debounce } from 'lodash-es'
import useMd5 from '@/utils/useMd5'
import { useTimeUtils } from '@/utils/time'
const userTime = useTimeUtils();

// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()
const md5 = useMd5();

// 响应式数据
const form = reactive({
    account: '',
    passwd: '',
    captcha: '',
    code:'',
    type: 2
})

const isCode = ref(false)
const itTop = ref('')
const isLoading = ref(false)
const codeimg = ref('')
const showPassword = ref(false)
const rememberPassword = ref(false)
const ecyz = ref(false)

// 方法
const togglePassword = () => {
    showPassword.value = !showPassword.value
}
const ecyzlist = () => {
    if(ecyz.value){
        ecyz.value = false;
    }else{
        ecyz.value = true;
    }
}
const toggleRememberPassword = () => {
    rememberPassword.value = !rememberPassword.value
}

const getCode = debounce(async () => {
    try {
        const res = await userStore.getCode()
        form.captcha = ''
        codeimg.value = res.data.data
        localStorage.removeItem('auuids')
        localStorage.setItem('auuid', res.data.uuid)
    } catch (error) {
        console.log('获取验证码失败')
    }
}, 300)

const bdownload = (type: number) => {
    const urls = {
        1: 'https://www.google.com/chrome/',
        2: 'http://www.ucweb.com/',
        3: 'https://support.apple.com/downloads/safari',
        4: 'https://www.mozilla.org/'
    }
    window.open(urls[type as keyof typeof urls], '_blank')
}

const getTop = () => {
    const u = navigator.userAgent
    const isAndroid = u.indexOf('Android') > -1 || u.indexOf('Linux') > -1
    const isIOS = !!u.match(/\(i[^;]+;( U;)? CPU.+Mac OS X/)
    
    itTop.value = isAndroid ? 'login-cont' : ''
}

const validateForm = (): boolean => {
    const { account, passwd, captcha } = form
    
    if (!(account.length > 3 && account.length < 18)) {
        showToast('用户名长度在 3 到 18 个字符')
        return false
    }
    
    if (!/^\S+$/.test(account)) {
        showToast('用户名不能为空')
        return false
    }
    
    if (!/^\S+$/.test(passwd)) {
        showToast('密码不能为空')
        return false
    }
    
    if (!/^\S+$/.test(captcha)) {
        showToast('验证码不能为空')
        return false
    }
    
    return true
}

const submitForm = async () => {
    if (isLoading.value) return
    
    if (!validateForm()) return
    
    isLoading.value = true
    
    try {
        // 密码加密
        const paw = form.passwd.toLowerCase()
        const password = md5(paw)
        form.type  = 2;
        const loginData = {
            ...form,
            password
        }
        
        const res = await userStore.login(loginData)
        
        if (res.code === 200) {
            localStorage.setItem('userInfo', JSON.stringify(res.data))
            localStorage.setItem('changePwds', res.data.isInit)
            localStorage.setItem('awebsock', res.data.wbUrl)
            if(res.data.sys==1){
                userTime.count(res.data.yearFlag);
            }
            
            localStorage.setItem('auuids', localStorage.getItem('auuid') || '')
            
            // 记住密码
            if (rememberPassword.value) {
                const accountInfo = { acout: form.account, pass: paw }
                localStorage.setItem('acout', JSON.stringify(accountInfo))
                localStorage.setItem('ispas', 'true')
            }
            router.push('/Notice')
        } else {
            showToast({
                title: res.message,
                icon: 'none',
                className: 'custom-toast',
                duration: 3000  
            })
            await getCode()
        }
    } catch (error) {
        await getCode()
    } finally {
        isLoading.value = false
    }
}

// 生命周期
onMounted(() => {
    // 清理本地存储
    localStorage.clear()
    
    // 关闭 WebSocket 连接
    // if (userStore.socket?.ws) {
    //     userStore.socket.close()
    // }
    
    // 加载保存的账号密码
    const savedAccount = localStorage.getItem('acout')
    const savedRemember = localStorage.getItem('ispas')
    
    if (savedAccount) {
        try {
            const accountInfo = JSON.parse(savedAccount)
            form.account = accountInfo.acout
            form.passwd = accountInfo.pass
            rememberPassword.value = savedRemember === 'true'
        } catch (error) {
            console.error('解析保存的账号信息失败')
        }
    }
    
    // 获取验证码
    getCode()
})
</script>

<style lang="less" scoped>
