    text-shadow: 0 -2.8px 2.2px rgba(170, 175, 195, 0.02), 0 -6.7px 5.3px rgba(170, 175, 195, 0.03), 0 -12.5px 10px rgba(170, 175, 195, 0.04), 0 -22.3px 17.9px rgba(170, 175, 195, 0.04), 0 -41.8px 33.4px rgba(170, 175, 195, 0.05), 0 -100px 80px rgba(170, 175, 195, 0.07);
    background-image: linear-gradient(180deg, #EAF2FF 0%, #FCFDFF 10%, #EAF2FF 90%, #F8FBFF 100%);
    font-family: Arial;
